-- Seed 唐僧 (Tang Seng) as a Café visitor. Generated by
-- .claude/skills/add-cafe-character/scripts/build-seed.mjs from content/characters/tang-seng.json.
-- Idempotent: safe to run again. Once seeded, Shop Admin → Café Characters is the place to
-- edit the character; this file never overwrites those edits.
--
-- Dev:  npx supabase db query --linked -f supabase/manual/2026-11-26-seed-cafe-tang-seng.sql
-- Prod: only when the owner asks, with .claude/skills/add-cafe-character/scripts/run-prod-sql.mjs

begin;

insert into shop_characters (
  character_key, name_i18n, intro_i18n, token_name_i18n, token_icon_path,
  sprite_paths, lines_i18n, visits_cafe, is_active, display_order, visit_frequency, visit_limit
) values (
  $seed$tang-seng$seed$,
  $seed${"en":"Tang Seng","zh":"唐僧"}$seed$::jsonb,
  $seed${"en":"The monk from Journey to the West. He only eats vegetarian food!","zh":"《西游记》里的唐僧，只吃素食！"}$seed$::jsonb,
  $seed${"en":"travel stamp","zh":"通关印"}$seed$::jsonb,
  $seed$/characters/tang-seng/tang-seng_token.png$seed$,
  $seed${"waiting":"/characters/tang-seng/tang-seng_waiting.png","delighted":"/characters/tang-seng/tang-seng_delighted.png"}$seed$::jsonb,
  $seed${"order":[{"en":"I've come a long way from Tang. A simple meal, please?","zh":"贫僧从东土大唐来，想讨一份素斋。"},{"en":"Amituofo! May I have some vegetarian food?","zh":"阿弥陀佛！请给贫僧来点素食吧。"},{"en":"We've walked so far. My disciples are hungry too!","zh":"走了好远的路，徒儿们也饿了。"}],"served":[{"en":"Thank you, kind friend! What a tasty meal.","zh":"多谢施主！这顿素斋真香。"},{"en":"Now I have the strength to keep heading west!","zh":"吃饱了，贫僧又有力气西行了！"},{"en":"How kind! Here's a stamp from my travel pass.","zh":"善哉善哉！送你一枚通关印。"}],"dismissed":[{"en":"No matter. I'll come by another day.","zh":"不要紧，贫僧改日再来。"},{"en":"Then I'll be on my way. Farewell!","zh":"那贫僧先去赶路啦，再会！"}]}$seed$::jsonb,
  true,
  true,
  (select coalesce(max(display_order) + 1, 0) from shop_characters),
  $seed$daily$seed$,
  6
)
on conflict (character_key) do nothing;

-- Orders: only if the character has none yet, so admin edits are never overwritten.
do $do$
declare
  v_orders jsonb := $seed$[{"tokenPrice":1,"items":[{"recipe":"noodle","quantity":1,"specialIngredients":[]}]},{"tokenPrice":2,"items":[{"recipe":"bun","quantity":2,"specialIngredients":["red-bean"]}]},{"tokenPrice":2,"items":[{"recipe":"rice_ball","quantity":2}]},{"tokenPrice":4,"items":[{"recipe":"noodle","quantity":1,"specialIngredients":[]},{"recipe":"bun","quantity":1,"specialIngredients":["red-bean"]},{"recipe":"rice_ball","quantity":1}]}]$seed$::jsonb;
  v_order jsonb;
  v_order_id uuid;
  v_bad text;
  v_index integer := 0;
begin
  select string_agg(distinct item ->> 'recipe', ', ') into v_bad
  from jsonb_array_elements(v_orders) o, jsonb_array_elements(o -> 'items') item
  where not exists (
    select 1 from shop_recipes r
    where r.slug = item ->> 'recipe' and r.is_active and r.cook_method is not null
  );
  if v_bad is not null then
    raise exception 'Recipes missing, inactive or not cookable: %', v_bad;
  end if;

  -- A pinned variant may only use the recipe's own special ingredients.
  select string_agg(distinct (item ->> 'recipe') || ' + ' || key, ', ') into v_bad
  from jsonb_array_elements(v_orders) o
  cross join lateral jsonb_array_elements(o -> 'items') item
  cross join lateral jsonb_array_elements_text(coalesce(item -> 'specialIngredients', '[]'::jsonb)) as k(key)
  join shop_recipes r on r.slug = item ->> 'recipe'
  where not exists (
    select 1 from jsonb_array_elements(coalesce(r.special_ingredient_slots, '[]'::jsonb)) slot
    where slot ->> 'ingredientKey' = key
  );
  if v_bad is not null then
    raise exception 'Special ingredients these recipes do not offer: %', v_bad;
  end if;

  if exists (select 1 from shop_character_orders where character_key = $seed$tang-seng$seed$) then
    return;
  end if;

  for v_order in select * from jsonb_array_elements(v_orders) loop
    insert into shop_character_orders (character_key, token_price, display_order)
    values ($seed$tang-seng$seed$, (v_order ->> 'tokenPrice')::integer, v_index)
    returning id into v_order_id;

    insert into shop_character_order_items (order_id, recipe_id, quantity, special_ingredient_keys)
    select v_order_id, r.id, (item ->> 'quantity')::integer, item -> 'specialIngredients'
    from jsonb_array_elements(v_order -> 'items') item
    join shop_recipes r on r.slug = item ->> 'recipe';

    v_index := v_index + 1;
  end loop;
end;
$do$;

-- Token content: skips any title the character already has.
insert into shop_character_token_contents (character_key, title, body, display_order)
select $seed$tang-seng$seed$, c.title, c.body, c.ord
from (values
  ($seed$五行山救悟空$seed$, $seed$唐僧路过五行山，揭下山顶的金字帖子。被压了五百年的孙悟空跳了出来，拜唐僧为师，保护师父去西天取经。$seed$, 0),
  ($seed$鹰愁涧收白龙马$seed$, $seed$在鹰愁涧，一条小白龙吃掉了唐僧的马。观音菩萨让小白龙变成一匹白马，驮着唐僧一路西行。$seed$, 1),
  ($seed$高老庄收八戒$seed$, $seed$在高老庄，悟空降服了猪八戒。八戒拜唐僧为师，从此跟着师父去取经。$seed$, 2),
  ($seed$流沙河收沙僧$seed$, $seed$流沙河又宽又深，沙悟净就住在河里。他拜唐僧为师，帮大家渡过了河。师徒四人到齐了！$seed$, 3),
  ($seed$三打白骨精$seed$, $seed$白骨精三次变成人的样子来骗唐僧，都被悟空的火眼金睛看穿了。$seed$, 4),
  ($seed$女儿国$seed$, $seed$西梁女国里住的都是女子。女王想留唐僧做国王，可唐僧一心取经，还是告别女王，继续西行。$seed$, 5),
  ($seed$火焰山$seed$, $seed$火焰山的大火挡住了去路。悟空向铁扇公主借来芭蕉扇，扇灭了大火，师徒才过了山。$seed$, 6),
  ($seed$灵山取经$seed$, $seed$师徒经历了九九八十一难，终于来到灵山，见到如来佛祖，取得了真经。$seed$, 7)
) as c(title, body, ord)
where not exists (
  select 1 from shop_character_token_contents t where t.character_key = $seed$tang-seng$seed$ and t.title = c.title
);

commit;
